head.script:
// 테스트 설명, 유효성 값 설정
//  _2 : columnInfo 파라미터를 Column ID(문자열)로 지정하는 분리 샘플 (_1 은 인덱스 지정)
scwin.tData = {
    "description" : "[gridView > M > setCellAllowChar]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 입력 가능한 문자의 집합을 정규식의 문자클래스 형식으로 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 Column 의 ID 를 설정하여 입력 가능한 문자의 집합을 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼은 inputType=custom + typeGetter(col1=text / col2=text / col3=textImage / col4=secret).\n[절차] rowIndex / columnInfo(Column ID) / allowChar 선택 -> setCellAllowChar 실행 -> 해당 셀을 더블클릭하여 허용 안 된 문자가 섞인 값 입력 후 포커스 아웃.\n[확인] columnInfo 를 인덱스 대신 Column ID(col1~col4) 로 지정해도 동일 동작. 실행 직후 기존 셀값의 허용 안 된 문자가 제거되고(before/after 출력), 편집 입력값도 허용 문자만 남아 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (영문+숫자+특수문자 혼합 -> allowChar 필터 결과가 보이도록)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "Ab1-c2", "col2": "Hello12!", "col3": "9a8b7c", "col4": "X9-y8" },
        { "col1": "Zz9_8x", "col2": "World34?", "col3": "1q2w3e", "col4": "Q1-w2" },
        { "col1": "Mn5,6P", "col2": "Test56#", "col3": "5t6y7u", "col4": "E3-r4" },
        { "col1": "Kk7.8L", "col2": "Code78@", "col3": "8i9o0p", "col4": "T5-y6" }
    ]);

    // target 생성
    //  4개 컬럼 모두 inputType=custom + typeGetter 로 Cell 의 inputType 을 각각 다르게 구성 (allow-list : text/input/textImage/secret)
    //  Body custom 컬럼 id 는 dataList 컬럼(col1~col4)과 일치시켜 셀 편집이 가능하도록 함
    //   col1 : Cell inputType=text       (메서드 allow-list O)
    //   col2 : Cell inputType=text       (메서드 allow-list O)
    //   col3 : Cell inputType=textImage  (메서드 allow-list O)
    //   col4 : Cell inputType=secret     (메서드 allow-list O)
    //   ※ inputType=input 은 가이드 allow-list 이나 엔진 getInput 이 input 객체를 반환하지 못해 미동작(MCP 실측). 동작 보장 위해 col2 는 text 로 구성.
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" viewChangeAfterEdit="true" ev:onafteredit="scwin.target1_onafteredit" dataList="data:dlt_bind" id="" style="width:640px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" inputType="text" id="hcol1" value="Cell text (custom)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol2" value="Cell text (custom)"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="hcol3" value="Cell textImage (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="Cell secret (custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="160" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_text2TypeGetter"></w2:column>';
    strTarget += '<w2:column width="160" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_textImageTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_secretTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// col1(custom) : 각 Cell 을 inputType=text 로 구성
scwin.target1_textTypeGetter = function (info) {
    return { id: 'cell_text_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', options: {} };
};
// col2(custom) : 각 Cell 을 inputType=text 로 구성
scwin.target1_text2TypeGetter = function (info) {
    return { id: 'cell_text2_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', options: {} };
};
// col3(custom) : 각 Cell 을 inputType=textImage 로 구성
scwin.target1_textImageTypeGetter = function (info) {
    return { id: 'cell_textImage_' + info.rowIndex + '_' + info.colIndex, inputType: 'textImage', options: { viewType: 'icon', imageSrc: '/cm/images/base/ico_grid_del.svg' } };
};
// col4(custom) : 각 Cell 을 inputType=secret 로 구성
scwin.target1_secretTypeGetter = function (info) {
    return { id: 'cell_secret_' + info.rowIndex + '_' + info.colIndex, inputType: 'secret', options: {} };
};



// setCellAllowChar 실행 : columnInfo 를 Column ID(문자열)로 그대로 지정하여 허용 문자 집합을 적용
//  _2 : columnInfo 를 Number 변환하지 않고 Column ID(문자열) 그대로 전달
//  실행 직후 기존 셀 데이터의 허용 안 된 문자가 제거되므로 before/after 를 함께 출력
scwin.btn_setCellAllowChar_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = par_columnInfo.getValue();
    let allowChar = par_allowChar.getValue();

    let beforeVal = scwin.target1.getCellData(rowIndex, columnInfo);
    let ret = scwin.target1.setCellAllowChar(rowIndex, columnInfo, allowChar);
    let afterVal = scwin.target1.getCellData(rowIndex, columnInfo);

    if (ret === false) {
        wf_body_bottom.getObj("scwin").setReturnValue(
            "setCellAllowChar(" + rowIndex + ", '" + columnInfo + "', '" + allowChar + "') : 전제 미충족 -> 미동작");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue(
            "setCellAllowChar(" + rowIndex + ", '" + columnInfo + "', '" + allowChar + "') 기존 셀값 필터 : '" + beforeVal + "' -> '" + afterVal + "'");
    }
}



// 셀 편집 종료(포커스 아웃) 시 발생 : allowChar 가 적용된 셀의 표시값을 출력
//  value 는 편집이 커밋된 후의 셀 값(= 허용 문자만 남은 결과)
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let colId = scwin.target1.getColumnID(columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit | [" + rowIndex + ", " + colId + "] 편집 입력값(allowChar 적용) : '" + value + "'");
}
